import sys

def main():
    sys.stdin.read()
    # Find one valid 6x10 pentomino tiling using DLX-like backtracking
    W, H = 10, 6
    # Define pentominoes as sets of (r,c) cells with origin normalized
    pieces = {
        'F': [(0,1),(0,2),(1,0),(1,1),(2,1)],
        'I': [(0,0),(0,1),(0,2),(0,3),(0,4)],
        'L': [(0,0),(1,0),(2,0),(3,0),(3,1)],
        'N': [(0,1),(1,1),(2,0),(2,1),(3,0)],
        'P': [(0,0),(0,1),(1,0),(1,1),(2,0)],
        'T': [(0,0),(0,1),(0,2),(1,1),(2,1)],
        'U': [(0,0),(0,2),(1,0),(1,1),(1,2)],
        'V': [(0,0),(1,0),(2,0),(2,1),(2,2)],
        'W': [(0,0),(1,0),(1,1),(2,1),(2,2)],
        'X': [(0,1),(1,0),(1,1),(1,2),(2,1)],
        'Y': [(0,1),(1,0),(1,1),(2,1),(3,1)],
        'Z': [(0,0),(0,1),(1,1),(2,1),(2,2)],
    }

    def normalize(cells):
        mr = min(r for r,c in cells)
        mc = min(c for r,c in cells)
        return tuple(sorted((r-mr, c-mc) for r,c in cells))

    def rotate(cells):
        return [(c, -r) for r,c in cells]

    def reflect(cells):
        return [(r, -c) for r,c in cells]

    def orientations(cells):
        seen = set()
        result = []
        cur = list(cells)
        for _ in range(4):
            n = normalize(cur)
            if n not in seen:
                seen.add(n)
                result.append(n)
            cur = rotate(cur)
        cur = reflect(cells)
        for _ in range(4):
            n = normalize(cur)
            if n not in seen:
                seen.add(n)
                result.append(n)
            cur = rotate(cur)
        return result

    piece_orients = {name: orientations(cells) for name, cells in pieces.items()}

    board = [[None]*W for _ in range(H)]
    used = set()

    def find_empty():
        for r in range(H):
            for c in range(W):
                if board[r][c] is None:
                    return r, c
        return None

    def solve():
        pos = find_empty()
        if pos is None:
            return True
        r, c = pos
        for name in sorted(piece_orients.keys()):
            if name in used:
                continue
            for orient in piece_orients[name]:
                # try placing so that the topmost-leftmost cell of orient is at (r,c)
                # find anchor: first cell in orient (sorted)
                ar, ac = orient[0]
                placed = []
                ok = True
                for dr, dc in orient:
                    nr = r + (dr - ar)
                    nc = c + (dc - ac)
                    if nr < 0 or nr >= H or nc < 0 or nc >= W or board[nr][nc] is not None:
                        ok = False
                        break
                    placed.append((nr, nc))
                if not ok:
                    continue
                for nr, nc in placed:
                    board[nr][nc] = name
                used.add(name)
                if solve():
                    return True
                for nr, nc in placed:
                    board[nr][nc] = None
                used.discard(name)
        return False

    solve()
    out = '\n'.join(''.join(row) for row in board)
    print(out)

main()
